"""Load the app's settings: defaults, then an optional config file, then APP_* variables."""
import os

DEFAULTS = {
    "host": "127.0.0.1",
    "port": 8080,
    "debug": False,
    "timeout": 5.0,
    "name": "inventory",
}

TRUE_WORDS = {"1", "true", "yes", "on"}
FALSE_WORDS = {"0", "false", "no", "off"}


def parse_bool(text):
    word = text.strip().lower()
    if word in TRUE_WORDS:
        return True
    if word in FALSE_WORDS:
        return False
    raise ValueError(f"not a yes/no value: {text!r}")


def coerce(key, text):
    """Turn raw text into the same type as the default for `key`."""
    default = DEFAULTS[key]
    if isinstance(default, bool):
        return parse_bool(text)
    if isinstance(default, int):
        return int(text)
    if isinstance(default, float):
        return float(text)
    return text


def read_file(path):
    """Read `key = value` lines; blank lines and # comments are skipped."""
    values = {}
    with open(path) as fh:
        for line in fh:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            key, _, raw = line.partition("=")
            key = key.strip()
            if key in DEFAULTS:
                values[key] = coerce(key, raw.strip())
    return values


def load_settings(path=None, environ=None):
    """Later sources win: defaults < config file < environment."""
    environ = os.environ if environ is None else environ
    settings = dict(DEFAULTS)
    if path:
        settings.update(read_file(path))
    for key in DEFAULTS:
        env_key = "APP_" + key.upper()
        if env_key in environ:
            settings[key] = coerce(key, environ[env_key])
    return settings

