"""Durations for the job scheduler config, e.g. `every = 90s` or `timeout = 2h`."""
import re

UNITS = {"s": 1, "m": 60, "h": 3600, "d": 86400}


def parse_duration(text):
    """Return the number of seconds in a duration like '90s', '2h' or '1h30m' (the parts add up)."""
    compact = text.strip()
    if not re.fullmatch(r"(?:\d+\s*[smhd]\s*)+", compact):
        raise ValueError(f"bad duration: {text!r}")
    return sum(int(n) * UNITS[u] for n, u in re.findall(r"(\d+)\s*([smhd])", compact))


def format_duration(seconds):
    """The reverse, for log messages: 5400 -> '1h30m'."""
    parts = []
    for unit in ("d", "h", "m", "s"):
        size = UNITS[unit]
        if seconds >= size:
            parts.append(f"{seconds // size}{unit}")
            seconds %= size
    return "".join(parts) or "0s"

