"""Tidy up the customer export from the booking site."""
import csv

FIELDS = ["email", "name", "phone", "signed_up"]


def load(path):
    with open(path, newline="") as fh:
        return list(csv.DictReader(fh))


def normalize_email(email):
    """Emails are compared ignoring capital letters and surrounding spaces."""
    return email.strip().lower()


def dedupe(rows):
    """Return one row per customer. Customers are matched by email; the latest sign-up wins."""
    latest = {}
    for row in rows:
        key = normalize_email(row["email"])
        if key not in latest or row["signed_up"] > latest[key]["signed_up"]:
            latest[key] = row
    return list(latest.values())


def write(path, rows):
    with open(path, "w", newline="") as fh:
        writer = csv.DictWriter(fh, fieldnames=FIELDS)
        writer.writeheader()
        writer.writerows(rows)


def main(src="export.csv", dest="customers_clean.csv"):
    write(dest, dedupe(load(src)))


if __name__ == "__main__":
    main()

