"""A tiny habit tracker that keeps everything in one JSON file."""
import json
import os

DATA_FILE = os.path.expanduser("~/.habit.json")
DEFAULT = {"settings": {"daily_goal": 8, "unit": "glasses"}, "entries": []}


def load(path):
    if not os.path.exists(path):
        return json.loads(json.dumps(DEFAULT))
    with open(path) as fh:
        return json.load(fh)


def save(path, data):
    with open(path, "w") as fh:
        json.dump(data, fh, indent=2)


def log(path, day, amount):
    data = load(path)
    data["entries"].append({"day": day, "amount": amount})
    save(path, data)


def total_for(path, day):
    return sum(e["amount"] for e in load(path)["entries"] if e["day"] == day)


def set_goal(path, goal):
    data = load(path)
    data["settings"]["daily_goal"] = goal
    save(path, data)


def reset(path):
    """Start over: drop every logged entry but keep the settings."""
    data = load(path)
    data["entries"] = []
    save(path, data)


def main(argv, path=DATA_FILE):
    if not argv:
        print("usage: habit log DAY AMOUNT | total DAY | goal N | reset")
        return 2
    cmd, args = argv[0], argv[1:]
    if cmd == "log":
        log(path, args[0], int(args[1]))
    elif cmd == "total":
        print(total_for(path, args[0]))
    elif cmd == "goal":
        set_goal(path, int(args[0]))
    elif cmd == "reset":
        reset(path)
    else:
        print(f"unknown command: {cmd}")
        return 2
    return 0

