import json
import re

MAX_NAME = 32  # the archive server rejects file names (including ".zip") longer than this


def slug(text):
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")


def load_projects(path="projects.json"):
    """A list of {"name": ..., "code": ...} dicts."""
    with open(path) as fh:
        return json.load(fh)


def archive_name(project, day):
    """project: a dict from projects.json; day: a date."""
    stamp = f"_{day:%Y%m%d}.zip"
    name = slug(project["name"]) + stamp
    if len(name) > MAX_NAME:
        name = slug(project["code"]) + stamp
    return name

